program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            by_color = {}
            for y, x in comp:
                by_color.setdefault(grid[y][x], []).append((y, x))
            def extent(color):
                cells = by_color[color]
                return (max(y for y, x in cells) - min(y for y, x in cells) + 1) * (max(x for y, x in cells) - min(x for y, x in cells) + 1)
            colors = sorted(by_color, key=extent)
            reversed_colors = colors[::-1]
            remap = dict(zip(colors, reversed_colors))
            for y, x in comp:
                out[y][x] = remap[grid[y][x]]
    return out
'''
